def longestSubstring(N: int, S: str) -> str:
    longest = -1
    result = ""
    for i in range(N):
        for j in range(i + 1, N):
            substring = S[i:j]
            if S.count(substring) >= 2 and all(S[x:x+len(substring)] != S[x+len(substring):x+2*len(substring)] for x in range(N - len(substring) + 1)):
                if len(substring) > longest:
                    longest = len(substring)
                    result = substring
    return result if result else "-1"
